class _IconPainter extends CustomPainter {
  _IconPainter(this.icon, this.color, this.strokeWidth);

  final AppIcon icon;
  final Color color;
  final double strokeWidth;

  @override
  void paint(Canvas canvas, Size size) {
    canvas.scale(size.width / 24, size.height / 24);
    final Paint paint = Paint()
      ..color = color
      ..style = PaintingStyle.stroke
      ..strokeWidth = strokeWidth
      ..strokeCap = StrokeCap.round
      ..strokeJoin = StrokeJoin.round;
    final Path path = Path();
    switch (icon) {
      case AppIcon.home:
        // M3 10.5 12 3l9 7.5V20a1 1 0 0 1-1 1h-5v-6H9v6H4a1 1 0 0 1-1-1z
        path
          ..moveTo(3, 10.5)
          ..lineTo(12, 3)
          ..lineTo(21, 10.5)
          ..lineTo(21, 20)
          ..arcToPoint(const Offset(20, 21), radius: const Radius.circular(1))
          ..lineTo(15, 21)
          ..lineTo(15, 15)
          ..lineTo(9, 15)
          ..lineTo(9, 21)
          ..lineTo(4, 21)
          ..arcToPoint(const Offset(3, 20), radius: const Radius.circular(1))
          ..close();
      case AppIcon.search:
        path
          ..addOval(Rect.fromCircle(center: const Offset(11, 11), radius: 7))
          ..moveTo(20, 20)
          ..lineTo(16.5, 16.5);
      case AppIcon.cart:
        path
          ..moveTo(6, 7)
          ..lineTo(18, 7)
          ..lineTo(17, 20)
          ..lineTo(7, 20)
          ..close()
          ..moveTo(9, 7)
          ..arcToPoint(const Offset(15, 7), radius: const Radius.circular(3));
      case AppIcon.back:
        path
          ..moveTo(15, 5)
          ..lineTo(8, 12)
          ..lineTo(15, 19);
      case AppIcon.minus:
        path
          ..moveTo(5, 12)
          ..lineTo(19, 12);
      case AppIcon.plus:
        path
          ..moveTo(12, 5)
          ..lineTo(12, 19)
          ..moveTo(5, 12)
          ..lineTo(19, 12);
      case AppIcon.alert:
        path
          ..addOval(Rect.fromCircle(center: const Offset(12, 12), radius: 9))
          ..moveTo(12, 7.5)
          ..lineTo(12, 13)
          ..moveTo(12, 16.5)
          ..lineTo(12.01, 16.5);
    }
    canvas.drawPath(path, paint);
  }

  @override
  bool shouldRepaint(_IconPainter old) =>
      old.icon != icon || old.color != color || old.strokeWidth != strokeWidth;
}

