          ..addOval(Rect.fromCircle(center: const Offset(12, 12), radius: 9))
          ..moveTo(12, 7.5)
          ..lineTo(12, 13)
          ..moveTo(12, 16.5)
          ..lineTo(12.01, 16.5);
    }
    canvas.drawPath(path, paint);
  }

