const MethodChannel _logChannel = MethodChannel('shopbench/log');
bool _homeReadyLogged = false;

void _logHomeReady() {
  if (_homeReadyLogged) return;
  _homeReadyLogged = true;
  if (Platform.isIOS) {
    _logChannel.invokeMethod<void>('homeReady').catchError((Object _) {});
  }
}

class HomeScreen extends StatefulWidget {
  const HomeScreen({super.key});

  @override
  State<HomeScreen> createState() => _HomeScreenState();
}

class _HomeScreenState extends State<HomeScreen> {
  HomeData? _data;
  bool _error = false;

  @override
  void initState() {
    super.initState();
    _load();
  }

  Future<void> _load() async {
    setState(() {
      _error = false;
      _data = null;
    });
    try {
      final HomeData data = await StorefrontApi.instance.home();
      if (!mounted) return;
      setState(() => _data = data);
      WidgetsBinding.instance.addPostFrameCallback((_) => _logHomeReady());
    } catch (_) {
      if (mounted) setState(() => _error = true);
    }
  }

  @override
  Widget build(BuildContext context) {
    return Screen(
      child: SafeArea(
        bottom: false,
        child: _error
            ? Column(
                children: <Widget>[
                  const _Header(),
                  Expanded(child: ErrorState(onRetry: _load)),
                ],
              )
            : _data == null
                ? const _HomeSkeleton()
                : _HomeContent(data: _data!),
      ),
    );
  }
}

