import '../api.dart';
import '../theme.dart';
import '../widgets.dart';

const MethodChannel _logChannel = MethodChannel('shopbench/log');
bool _homeReadyLogged = false;

void _logHomeReady() {
  if (_homeReadyLogged) return;
  _homeReadyLogged = true;
  if (Platform.isIOS) {
    _logChannel.invokeMethod<void>('homeReady').catchError((Object _) {});
  }
}

class HomeScreen extends StatefulWidget {
  const HomeScreen({super.key});

  @override
  State<HomeScreen> createState() => _HomeScreenState();
}

class _HomeScreenState extends State<HomeScreen> {
  HomeData? _data;
  bool _error = false;

  @override
  void initState() {
    super.initState();
    _load();
  }

  Future<void> _load() async {
    setState(() {
      _error = false;
      _data = null;
    });
    try {
      final HomeData data = await StorefrontApi.instance.home();
      if (!mounted) return;
      setState(() => _data = data);
      WidgetsBinding.instance.addPostFrameCallback((_) => _logHomeReady());
    } catch (_) {
      if (mounted) setState(() => _error = true);
    }
  }

  @override
  Widget build(BuildContext context) {
    return Screen(
      child: SafeArea(
        bottom: false,
        child: _error
            ? Column(
                children: <Widget>[
                  const _Header(),
                  Expanded(child: ErrorState(onRetry: _load)),
                ],
              )
            : _data == null
                ? const _HomeSkeleton()
                : _HomeContent(data: _data!),
      ),
    );
  }
}

class _Header extends StatelessWidget {
  const _Header();

  @override
  Widget build(BuildContext context) {
    return Container(
      height: 44,
      padding: const EdgeInsets.symmetric(horizontal: 16),
      alignment: Alignment.centerLeft,
      child: Text('Everbloom', style: ts(22, weight: FontWeight.w700, letterSpacing: -0.4)),
    );
  }
}

class _HomeSkeleton extends StatelessWidget {
  const _HomeSkeleton();

  @override
  Widget build(BuildContext context) {
    return const SingleChildScrollView(
      physics: NeverScrollableScrollPhysics(),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: <Widget>[
          _Header(),
          Padding(
            padding: EdgeInsets.fromLTRB(16, 8, 16, 12),
            child: Row(
              children: <Widget>[
                SkeletonBox(width: 52, height: 36, radius: 999),
                SizedBox(width: 8),
                SkeletonBox(width: 110, height: 36, radius: 999),
                SizedBox(width: 8),
                SkeletonBox(width: 96, height: 36, radius: 999),
                SizedBox(width: 8),
                SkeletonBox(width: 80, height: 36, radius: 999),
              ],
            ),
          ),
          Padding(
            padding: EdgeInsets.fromLTRB(16, 4, 16, 0),
            child: SkeletonBox(height: 240, radius: 12),
          ),
          Padding(
            padding: EdgeInsets.fromLTRB(16, 28, 16, 12),
            child: SkeletonBox(width: 120, height: 18, radius: 4),
          ),
          Padding(
            padding: EdgeInsets.symmetric(horizontal: 16),
            child: Row(
              children: <Widget>[
                SkeletonBox(width: 140, height: 175),
                SizedBox(width: 12),
                SkeletonBox(width: 140, height: 175),
                SizedBox(width: 12),
                Expanded(child: SkeletonBox(height: 175)),
